#!/usr/bin/env python3
"""Build crawlable pages. Run: python3 scripts/build.py --origin https://your-domain.com"""
import json, pathlib, html, argparse, re, datetime
from rich_html import sanitize_rich_html
from format_html import format_html
root=pathlib.Path(__file__).resolve().parents[1]; d=root/'dist'
p=argparse.ArgumentParser();p.add_argument('--origin',default=None);p.add_argument('--snapshot');args=p.parse_args();previous_settings=json.loads((d/'settings.json').read_text(encoding='utf-8')) if (d/'settings.json').exists() else {};origin=(args.origin if args.origin is not None else previous_settings.get('origin','')).rstrip('/')
if origin and not re.fullmatch(r'https://[A-Za-z0-9.-]+(?::\d+)?',origin):raise SystemExit('Use an HTTPS origin without a path')
snapshot=json.loads(pathlib.Path(args.snapshot).read_text(encoding='utf-8')) if args.snapshot else {}
courses=snapshot.get('courses',json.loads((d/'catalog.json').read_text(encoding='utf-8')));posts=snapshot.get('posts',json.loads((d/'posts.json').read_text(encoding='utf-8')));esc=lambda x:html.escape(str(x),quote=True)
courses=[c for c in courses if c.get('published') is True];posts=[a for a in posts if a.get('published') is True]
from urllib.parse import urlsplit
for c in courses:
 u=urlsplit(c.get('checkout',''))
 if u.scheme!='https' or u.hostname not in ['selar.com','www.selar.com']:raise SystemExit('Course checkout must be an HTTPS Selar URL')
 if not re.fullmatch(r'[a-zA-Z0-9_-]{1,100}',c['id']):raise SystemExit('Invalid course ID')
for a in posts:
 if not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',a['slug']):raise SystemExit('Invalid post slug')
for item in courses+posts:
 u=urlsplit(item.get('image',''))
 if not item.get('image') or (u.scheme and u.scheme!='https') or (u.netloc and u.scheme!='https'):raise SystemExit('Use a local image path or HTTPS image URL')
# Only generated HTML within these two directories is replaced.
for folder in ['courses','journal']:
 if (d/folder).exists():
  for generated in (d/folder).glob('*.html'):generated.unlink()
(d/'catalog.json').write_text(json.dumps(courses,indent=2), encoding='utf-8');(d/'posts.json').write_text(json.dumps(posts,indent=2), encoding='utf-8')
settings={'headline':'Make something beautifully yours.','intro':'Learn the craft behind beautiful clothes. Thoughtful online fashion classes in pattern drafting, garment construction and the details that make all the difference.','email':'isewfashionacademy@gmail.com','whatsapp':'2348059744860','origin':origin}
settings.update({k:v for k,v in previous_settings.items() if k in ['headline','intro','email','whatsapp']});settings.update({k:v for k,v in snapshot.get('settings',{}).items() if k in ['headline','intro','email','whatsapp']});settings['origin']=origin
if not re.fullmatch(r'[^\s@<>"\x27]+@[^\s@<>"\x27]+\.[^\s@<>"\x27]+',settings['email']):raise SystemExit('Invalid contact email')
if not re.fullmatch(r'[0-9]{10,15}',settings['whatsapp']):raise SystemExit('Invalid WhatsApp number')
(d/'settings.json').write_text(json.dumps(settings,indent=2), encoding='utf-8')
links=[('index.html','Home'),('courses.html','Classes'),('about.html','Our story'),('journal.html','Journal'),('contact.html','Contact')]
faq=[('Which class should I start with?','Choose by the garment you want to make and your current skills. Each course page outlines its focus. Message Gracy before payment to confirm that the class suits your experience and available tools.'),('How do I enrol?','Choose a course, use its Selar checkout or message Gracy on WhatsApp, and confirm the current schedule and class requirements. Keep your payment confirmation; Gracy will share the joining instructions.'),('Are the classes online?','The academy teaches online and uses community support and shared learning resources. Delivery differs by course, so confirm the session format, timetable and access arrangements before enrolling.'),('What equipment do I need?','A tape measure, drafting materials and access to suitable sewing equipment are useful for construction courses. Specialist materials depend on your class. Ask for the course materials list before buying supplies.'),('Can I join from outside Nigeria?','The original course information includes fees in several currencies, and Gracy teaches learners across Nigeria, Ghana and Kenya. Confirm payment options and your time zone directly before booking.'),('Will I receive a certificate?','Ask Gracy about certificates and completion requirements for the particular class you choose. Do not assume certification is included unless it is confirmed before payment.'),('Can I install the academy on my phone?','Yes, supported browsers can add the website to your home screen. On iPhone, open it in Safari and choose Share, then Add to Home Screen. On Android, use the install button when available or the browser menu.'),('What is the refund policy?','Contact the academy before paying to confirm the applicable refund, cancellation and rescheduling terms. No automatic refund entitlement or specific refund period is advertised on this site.')]
def asset(value):
 return value if urlsplit(value).scheme=='https' else '/'+value.lstrip('/')
stories=[x for x in snapshot.get('testimonials',[{'image':f'assets/testimonials/t{i}.jpg','alt':f'Original student feedback screenshot {i}; open image to read','published':True} for i in range(1,10)]) if x.get('published') is True]
for x in stories:
 u=urlsplit(x.get('image',''))
 if u.scheme not in ['','https'] or (u.netloc and u.scheme!='https'):raise SystemExit('Invalid student image URL')
