def brand():return '<a class="brand" href="/index.html"><img src="/assets/brand/logo.png" alt="ISew with Gracy logo" width="47" height="47"><span class="brand-name">ISew <em>with Gracy</em><small>THE FASHION ACADEMY</small></span></a>'
def share(title,url=''):
 return f'<button class="share-button" type="button" data-share="{esc(url)}" data-share-title="{esc(title)}" aria-label="Share {esc(title)}"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4M8.6 13.5l6.8 4"/></svg><span>Share</span></button>'
def discussion(postid=''):
 return f'''<section class="wrap section discussion" id="article-discussion" data-post="{esc(postid)}"><div class="section-head"><div><p class="eyebrow">CONTINUE THE CONVERSATION</p><h2>A thoughtful <em>exchange.</em></h2></div><p id="comment-count">Comments are reviewed before publication.</p></div><div class="discussion-grid"><div id="article-comments"><p class="status">Be the first to add a thoughtful note.</p></div><form class="comment-form" id="comment-form" data-post="{esc(postid)}"><h3>Leave a little inspiration.</h3><label class="field">Your name<input name="name" required maxlength="80" autocomplete="name"></label><label class="field">Your comment<textarea name="comment" required minlength="5" maxlength="1500" placeholder="What resonated with you?"></textarea></label><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><label class="check field"><input type="checkbox" required>I agree to publish my name and comment after moderation.</label><button class="btn" type="submit">Post comment ↗</button><p class="status" data-form-status>Keep it kind, useful and relevant to the story.</p></form></div></section>'''
