def postcard(a):return f'''<article class="card"><a class="card-image" href="/journal/{esc(a['slug'])}.html"><img src="{esc(asset(a['image']))}" alt="Sewing and garment construction in Gracy’s studio" width="600" height="400" loading="lazy"></a><div class="card-body"><p class="eyebrow">{esc(a['category'])} · 4 MIN READ</p><h3><a href="/journal/{esc(a['slug'])}.html">{esc(a['title'])}</a></h3><p>{esc(a['excerpt'])}</p><div class="story-links"><a class="text-link" href="/journal/{esc(a['slug'])}.html">Read the story ↗</a>{share(a['title'],'/journal/'+a['slug']+'.html')}</div></div></article>'''
def faqhtml(limit=None):return '<div class="faq">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in faq[:limit])+'</div>'
