 sd=schema or {'@context':'https://schema.org','@type':'EducationalOrganization','name':'ISew with Gracy','description':desc,**({'url':origin} if origin else {}),'email':settings['email']}
 j=json.dumps(sd,ensure_ascii=False).replace('<','\\u003c')
