page('index.html','Online Fashion Classes & Sewing Masterclasses','Learn pattern drafting, corsetry, blazer construction, trousers and beading with Gracy. Explore online fashion masterclasses and sewing resources.',f'''<section class="wrap hero"><div class="hero-copy"><p class="eyebrow">A CRAFT WORTH LEARNING</p><h1 data-headline>{esc(settings['headline']) if snapshot else 'Make something<br><em>beautifully yours.</em>'}</h1><p class="lede" data-intro>{esc(settings['intro'])}</p><div class="actions"><a class="btn" href="/courses.html">Explore masterclasses ↗</a><a class="text-link" href="/about.html">Meet your tutor</a></div><div class="mini-note"><span></span>Online classes. Real skills. Your own creative voice.</div></div><div class="hero-media"><span class="hero-orbit" aria-hidden="true">DESIGN<br>✳<br>CREATE</span><img src="/assets/hero/hero-1.jpg" alt="Gracy fitting a patterned bodice on a dress form in her studio" width="666" height="1000" fetchpriority="high"><div class="image-note"><strong>Made with intention.</strong><span>TAUGHT WITH HEART.</span></div><div class="hero-inset"><img src="/assets/hero/hero-4.jpg" alt="Garment detail from the studio" width="200" height="240" loading="lazy"></div></div></section><div class="marquee"><span>PATTERN DRAFTING <b>✧</b></span><span>GARMENT CONSTRUCTION <b>✧</b></span><span>BEAUTIFUL FINISHING <b>✧</b></span><span>YOUR CREATIVE JOURNEY</span></div><section class="wrap section"><div class="section-head"><div><p class="eyebrow">THE MASTERCLASS EDIT</p><h2>A new skill.<br><em>A new possibility.</em></h2></div><div><p>Focused classes for the details you want to master. Choose your next project and build from there.</p><a class="text-link" href="/courses.html">View all classes ↗</a></div></div><div class="grid" id="featured-courses">{''.join(card(c) for c in courses[:3])}</div></section><section class="subtle"><div class="wrap section split"><img class="portrait" src="/assets/hero/hero-2.jpg" width="666" height="1000" loading="lazy" alt="A glimpse into Gracy’s sewing studio"><div><p class="eyebrow">THE PERSON BEHIND THE PATTERNS</p><h2>Good teaching.<br><em>Beautiful making.</em></h2><p>Gracy founded ISew to share the skills behind clothes that fit and feel right. Her teaching brings measurement, drafting and construction together, one considered step at a time.</p><p>From Nigeria to Ghana and Kenya, the academy is a place to ask questions, practise your craft and develop a way of making that is your own.</p><a class="text-link" href="/about.html">Get to know the academy ↗</a><div class="signature">With care, Gracy.</div></div></div></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">A SIMPLE BEGINNING</p><h2>From curiosity<br><em>to creation.</em></h2></div><a class="text-link" href="/how-it-works.html">How learning works ↗</a></div><div class="step-grid"><div class="step"><b>01</b><h3>Find your focus.</h3><p>Choose a class around the garment or technique you want to learn.</p></div><div class="step"><b>02</b><h3>Make it official.</h3><p>Confirm the requirements and schedule, then enrol through Selar or speak with Gracy.</p></div><div class="step"><b>03</b><h3>Bring it to life.</h3><p>Follow the teaching, practise the techniques and get support as you work.</p></div></div></section><section class="wrap section home-stories"><div class="section-head"><div><p class="eyebrow">NOTES FROM OUR LEARNERS</p><h2>Real voices.<br><em>Beautiful journeys.</em></h2></div><a class="text-link" href="/student-stories.html">Meet the community ↗</a></div><div class="testimonial-grid" id="home-testimonials">{''.join(storycard(t) for t in stories[:3])}</div><p class="status">Original feedback from Gracy’s students.</p></section><section class="wrap section journal"><div class="section-head"><div><p class="eyebrow">NOTES FROM THE STUDIO</p><h2>The sewing <em>journal.</em></h2></div><a class="text-link" href="/journal.html">Read all stories ↗</a></div><div class="grid" id="journal-grid">{''.join(postcard(a) for a in posts)}</div></section>{cta()}''')
page('courses.html','Online Sewing & Fashion Masterclasses','Explore five practical online fashion courses in corsetry, blazer construction, trousers, beading and hip padding. Course fees and enrolment details included.',intro('Masterclasses','Find your next<br><em>creative chapter.</em>','A considered collection of classes. Learn the techniques behind garments you will be proud to make.')+f'''<section class="wrap section"><div class="filters" role="search"><label class="sr-label" for="course-search">Find a class</label><input type="search" id="course-search" placeholder="Search classes or techniques…"><button class="active" data-filter="All" aria-pressed="true">All classes</button><button data-filter="Construction" aria-pressed="false">Construction</button><button data-filter="Embellishment" aria-pressed="false">Embellishment</button></div><div class="grid" id="course-grid">{''.join(card(c) for c in courses)}</div><p class="status">Fees are retained from the original site. Confirm current pricing and availability before payment.</p></section>'''+cta())
for c in courses:
 body=intro('Masterclasses / '+c['title'],esc(c['title']),c['summary'])+'<div class="wrap page-tools">'+share(c['title'],'/courses/'+c['id']+'.html')+'</div>'+f'''<section class="wrap section course-layout"><div><p class="eyebrow">{esc(c['duration'])} · {esc(c['level'])}</p><h2>A closer look<br><em>at the craft.</em></h2><p data-course-description>{esc(c['description'])}</p><h3>What you’ll explore</h3><ul class="list">{''.join('<li>'+esc(x.strip().capitalize())+'</li>' for x in c['summary'].rstrip('.').split(', '))}</ul><h3>Before you begin</h3><p>Ask Gracy to confirm your starting skill level, required materials, class dates, delivery format and resource access. Have your measurements, drafting supplies and appropriate equipment ready.</p><div class="notice">Enrolment is handled through the academy’s existing Selar checkout or directly with Gracy. Card details are never collected on this website.</div><h3>Student reviews</h3><div id="course-reviews" data-course="{esc(c['id'])}"><p class="status">No published reviews to display yet.</p></div><details class="admin-card"><summary>Share your learning experience</summary><form id="review-form" data-course="{esc(c['id'])}"><label class="field">Your name<input name="name" required maxlength="80" autocomplete="name"></label><label class="field">Rating<select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Needs improvement</option><option value="1">1 — Disappointing</option></select></label><label class="field">Your experience<textarea name="comment" required minlength="10" maxlength="1500"></textarea></label><label class="check field"><input type="checkbox" required>I consent to my name and review being published after moderation.</label><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><button class="btn" type="submit">Submit for review ↗</button><p class="status" data-form-status></p></form></details></div><aside class="course-aside"><img src="{esc(asset(c['image']))}" alt="{esc(c['title'])} original course flyer" width="600" height="750"><div class="fee" data-course-fee>{esc(c['fee'].split(' · ')[0])}</div><p class="secondary-fee">{esc(c['fee'])}</p><a class="btn" data-checkout href="{esc(c['checkout'])}" target="_blank" rel="noopener noreferrer">Enrol through Selar ↗</a><a class="btn outline" data-whatsapp href="https://wa.me/{settings['whatsapp']}?text={__import__('urllib.parse',fromlist=['quote']).quote('Hello Gracy, I am interested in '+c['title']+'. Please confirm the schedule and requirements.')}" target="_blank" rel="noopener noreferrer">Ask about this class</a><p class="status">Please confirm current fees and availability.</p></aside></section>'''
 schema={'@context':'https://schema.org','@type':'Course','name':c['title'],'description':c['description'],'provider':{'@type':'EducationalOrganization','name':'ISew with Gracy'},'url':origin+'/courses/'+c['id']+'.html'}
 page('courses/'+c['id']+'.html',c['title'],c['summary'],body,schema)
page('about.html','Meet Gracy & the Fashion Academy','Meet the founder of ISew with Gracy, an online fashion academy teaching pattern drafting and garment construction to learners across Nigeria, Ghana and Kenya.',intro('Our story','A love of fashion.<br><em>A belief in your potential.</em>','Behind every beautifully made garment is a skill that can be taught, practised and made your own.')+'''<section class="wrap section split"><img class="portrait" src="/assets/hero/hero-1.jpg" alt="Gracy at work on a bodice" loading="lazy"><div><p class="eyebrow">MEET YOUR TUTOR</p><h2>Hello,<br><em>I’m Gracy.</em></h2><p>I am the tutor and founder behind ISew. I teach pattern drafting, cutting and construction to students across Nigeria, Ghana and Kenya.</p><p>My classes focus on accurate measurement, clear drafting and finishing you can be proud of. They are built around practical skills you can return to for your own projects and your clients.</p><p>The academy brings teaching, community support and learning resources together. Before joining, let us talk about your experience and what you want to make next.</p><div class="signature">Design. Draft. Create. Empower.</div></div></section><section class="subtle"><div class="wrap section"><p class="eyebrow">OUR APPROACH</p><h2>Thoughtful teaching,<br><em>from the first stitch.</em></h2><div class="values"><div class="value"><b>01</b><h3>Clear instruction</h3><p>Understand the reasons behind the measurement, pattern and construction.</p></div><div class="value"><b>02</b><h3>Practical making</h3><p>Build skills through garment techniques you can practise and repeat.</p></div><div class="value"><b>03</b><h3>Community support</h3><p>Ask about the academy’s Telegram and WhatsApp learning communities.</p></div><div class="value"><b>04</b><h3>Useful resources</h3><p>Ask about the measurement charts, pattern sheets and videos for your class.</p></div></div></div></section>'''+cta())
page('how-it-works.html','How Online Learning Works','Find a class, confirm the requirements and enrol. Understand how online learning and academy support work at ISew with Gracy.',intro('How it works','A clear path<br><em>to your next skill.</em>','Know what to expect before you enrol, and give yourself the space to practise.')+'''<section class="wrap section prose"><h2>01 / Choose with intention.</h2><p>Browse the masterclasses and read the course details. If you are unsure where to begin, tell Gracy what you already know, which equipment you have and what you want to make.</p><h2>02 / Confirm the details.</h2><p>Ask about dates, session times, delivery format, resource access and materials. Confirm the current fee in your payment currency and the cancellation terms before you pay.</p><h2>03 / Enrol securely.</h2><p>Use the original Selar course links or ask Gracy for the academy’s payment instructions. Keep your receipt. We do not ask you to enter card details on this website.</p><h2>04 / Join and make.</h2><p>Follow your joining instructions, prepare the required materials and practise alongside the lessons. Ask questions and use the resources available for your class.</p><a class="btn" href="/courses.html">Choose a masterclass ↗</a></section>''')
page('student-stories.html','Student Stories & Feedback','Read original student feedback from ISew with Gracy. See the messages preserved from the academy’s existing website.',intro('Student stories','A community<br><em>stitched together.</em>','Original messages from learners in Gracy’s classes, preserved from the academy’s website.')+'<section class="wrap section"><div class="testimonial-grid" id="testimonial-grid">'+''.join(storycard(t) for t in stories)+'</div><p class="status">Screenshots are original source material. They are not converted into star ratings or invented testimonials.</p></section>'+cta())
page('journal.html','The Sewing Journal — Tips & Pattern Notes','Read sewing guides, pattern drafting notes and garment finishing tips from the ISew with Gracy fashion academy.',intro('The journal','Notes on making.<br><em>Ideas worth keeping.</em>','A quieter corner of the academy for sewing essentials, thoughtful techniques and creative practice.')+f'<section class="wrap section journal"><div class="filters"><label for="journal-search">Find a story</label><input type="search" id="journal-search" placeholder="Search the journal…"></div><div class="grid" id="journal-grid">'+''.join(postcard(a) for a in posts)+'</div></section>')
for a in posts:
 schema={'@context':'https://schema.org','@type':'BlogPosting','headline':a['title'],'description':a['excerpt'],'datePublished':a['date'],'author':{'@type':'Organization','name':'ISew with Gracy'},'image':(asset(a['image']) if urlsplit(a['image']).scheme else origin+asset(a['image'])),'mainEntityOfPage':origin+'/journal/'+a['slug']+'.html'}
 page('journal/'+a['slug']+'.html',a['title'],a['excerpt'],intro('Journal / '+a['category'],esc(a['title']),a['excerpt'])+'<div class="wrap page-tools">'+share(a['title'],'/journal/'+a['slug']+'.html')+'</div><progress id="reading-progress" max="100" value="0" aria-label="Reading progress"></progress>'+f'<article class="wrap section prose" id="live-article" data-slug="{esc(a['slug'])}"><p class="eyebrow">ISEW EDITORIAL · {esc(a["date"])} · 4 MIN READ</p><img class="article-image" src="{esc(asset(a["image"]))}" alt="Fashion construction at the academy">'+'<div class="article-body prose">'+(sanitize_rich_html(a.get('bodyHtml')) if a.get('bodyHtml') else ''.join('<p>'+esc(x)+'</p>' for x in a['body'].split('\n\n')))+'</div>'+'<a class="text-link" href="/journal.html">← Back to the journal</a></article>'+discussion(a['id'])+cta(),schema)
page('resources.html','Sewing Resources & Getting Started','Prepare for your online sewing class with a practical equipment checklist and guidance on choosing your learning path.',intro('Getting started','A good beginning<br><em>changes everything.</em>','Simple preparations that help you get more from your next class.')+'''<section class="wrap section"><div class="grid"><div class="admin-card"><p class="eyebrow">YOUR TOOLKIT</p><h3>Keep it considered.</h3><ul class="list"><li>Flexible tape measure</li><li>Drafting paper and suitable rulers</li><li>Fabric scissors and paper scissors</li><li>Marking tools and pins or clips</li><li>Suitable sewing equipment</li><li>Test fabric for practice</li></ul><p class="status">Confirm the specific materials for your chosen course.</p></div><div class="admin-card"><p class="eyebrow">YOUR LEARNING SPACE</p><h3>Make room to make.</h3><p>A clear working surface, reliable light and somewhere to keep your patterns make practice easier. Test your connection before an online session and plan time for the practical work.</p></div><div class="admin-card"><p class="eyebrow">YOUR NEXT STEP</p><h3>Follow your curiosity.</h3><p>Explore corsetry for supportive bodices, blazer construction for tailoring, trousers for everyday fit, and beading for decorative detail.</p><a class="text-link" href="/courses.html">Explore the classes ↗</a></div></div></section>''')
page('faq.html','Frequently Asked Questions','Answers about course enrolment, equipment, online learning, international payments and installing the ISew academy app.',intro('Questions & answers','A little clarity.<br><em>A confident start.</em>','The details that matter before your first class.')+'<section class="wrap section">'+faqhtml()+'</section>'+cta())
page('contact.html','Contact Gracy — Course & Enrolment Enquiries','Ask Gracy about fashion masterclasses, course requirements, current fees and enrolment. Contact the academy by WhatsApp, email or enquiry form.',intro('Let’s connect','Your next skill<br><em>starts with a conversation.</em>','Tell us what you would love to make, and let us help you find the right class.')+f'''<section class="wrap section split"><div><img class="article-image" src="/assets/contact-1.jpg" alt="Gracy in her sewing studio" loading="lazy"><h3>Speak to the academy.</h3><p><a data-whatsapp class="text-link" href="https://wa.me/{settings['whatsapp']}" target="_blank" rel="noopener noreferrer">WhatsApp Gracy ↗</a></p><p><a data-email href="mailto:{settings['email']}">{settings['email']}</a></p><p class="status">Community links and joining instructions are shared after you contact the academy.</p></div><form class="admin-card" id="enquiry-form"><h3>Leave a thoughtful note.</h3><label class="field">Your name<input name="name" required maxlength="80" autocomplete="name"></label><label class="field">Email address<input name="email" type="email" required maxlength="200" autocomplete="email"></label><label class="field">What would you like to learn?<select name="course"><option value="Not sure yet">Help me choose</option>{''.join('<option>'+esc(c['title'])+'</option>' for c in courses)}</select></label><label class="field">Your message<textarea name="message" required minlength="10" maxlength="2000"></textarea></label><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><label class="check field"><input name="consent" type="checkbox" required>I agree to be contacted about this enquiry. <a href="/privacy.html">Privacy policy</a></label><button class="btn" type="submit">Send enquiry ↗</button><p class="status" data-form-status>Or use WhatsApp or email for a direct conversation.</p></form></section>''')
page('privacy.html','Privacy & Data Use','How ISew with Gracy handles enquiries, published reviews and essential website storage.',intro('Privacy','Your information,<br><em>treated with care.</em>','Privacy information for this website.')+'''<section class="wrap section prose"><h2>What we collect</h2><p>When you send an enquiry, the academy receives your name, email address, course interest and message. When you submit a review, your name, rating and comment are sent for moderation. Enquiries are private; approved reviews are public.</p><h2>How we use it</h2><p>Information is used to answer your enquiry, arrange course registration and moderate reviews. Contact the academy to request access, correction or deletion. The academy should review retention and applicable data protection requirements before launch.</p><h2>Essential website storage</h2><p>The site uses browser storage for announcement dismissals and app installation preferences. If you use the enquiry form, Firebase may establish an anonymous authentication session for submission validation. Admin login uses session authentication. No advertising trackers are included.</p><h2>Third-party services</h2><p>Firebase supports authentication and content when configured. Google Fonts supplies typography. Selar handles purchases on its own website. WhatsApp and social links take you to external services with their own privacy policies.</p><h2>Contact</h2><p><a data-email href="mailto:isewfashionacademy@gmail.com">isewfashionacademy@gmail.com</a></p></section>''')
page('terms.html','Learning & Website Terms','Understand enrolment confirmation, payment handling, course resources and website use at ISew with Gracy.',intro('Learning terms','Clear expectations.<br><em>Better experiences.</em>','Read these details before registering for a class.')+'''<section class="wrap section prose"><h2>Course information</h2><p>Fees, dates, format and materials can change. Confirm the current details with Gracy before payment. The course descriptions describe the techniques offered and do not promise income, accreditation or employment.</p><h2>Payment and cancellation</h2><p>Payments are handled by Selar or directly through the academy’s confirmed instructions. Ask for the applicable cancellation, refund and rescheduling policy before enrolling. This website does not collect card details.</p><h2>Learning materials</h2><p>Use resources supplied for your class for your own learning. Ask the academy before redistributing its videos, pattern sheets or other original materials.</p><h2>Reviews and messages</h2><p>Submit honest, relevant feedback. Do not include private financial information, passwords or someone else’s personal details. Reviews are moderated before publication.</p><h2>Questions</h2><p>Contact the academy if you need clarification about any class or term before purchase.</p></section>''')
adminbody='''<div id="login-view"><div class="login-hero">'''+brand()+'''</div><section class="admin-login"><p class="eyebrow">ACADEMY WORKSPACE</p><h1>Welcome<br><em>back.</em></h1><p>A considered space for everything you create.</p><form id="login-form"><label class="field">Admin email<input name="email" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required minlength="8"></label><button class="btn" type="submit">Open workspace ↗</button><p class="status" id="login-status"></p></form><button class="text-link" id="demo-button">Preview the workspace</button><p class="status">The preview uses sample data in memory. Connect Firebase to manage live content.</p><a class="text-link" href="/index.html">← Back to the academy</a></section></div><div class="admin-shell" id="workspace" hidden><aside class="admin-nav">'''+brand()+'''<nav class="admin-tabs" aria-label="Workspace sections"><button data-tab="overview" class="active">Overview</button><button data-tab="courses">Masterclasses</button><button data-tab="posts">Journal</button><button data-tab="testimonials">Student stories</button><button data-tab="reviews">Reviews</button><button data-tab="comments">Blog comments</button><button data-tab="enquiries">Enquiries</button><button data-tab="popups">Announcements</button><button data-tab="settings">Site settings</button></nav><a class="bottom" href="/index.html" target="_blank" rel="noopener">View academy ↗</a><button id="logout-button">Sign out</button></aside><section class="admin-main"><header class="admin-top"><div><p class="eyebrow">YOUR ACADEMY, THOUGHTFULLY MANAGED</p><h1 id="workspace-title">Overview</h1><p id="workspace-mode"></p></div><button class="btn outline small" id="export-button">Export content ↓</button></header><div id="admin-content"></div></section></div><dialog class="modal admin-editor" id="editor-modal" aria-labelledby="editor-title"><button class="close" data-close-dialog aria-label="Close editor">×</button><h2 id="editor-title">Edit content</h2><form id="editor-form"><div id="editor-fields" class="form-grid"></div><div class="actions"><button class="btn" type="submit">Save changes ↗</button><button class="btn outline" type="button" data-close-dialog>Cancel</button></div><p id="editor-status" class="status"></p></form></dialog><dialog class="modal" id="delete-modal" aria-labelledby="delete-title"><h2 id="delete-title">Remove this item?</h2><p>This removes the selected item from the academy. Export a backup first if you need to keep a copy.</p><div class="actions"><button class="btn" id="confirm-delete">Remove item</button><button class="btn outline" data-close-dialog>Keep it</button></div></dialog>'''
page('admin.html','Academy Admin Workspace','Secure admin workspace for ISew with Gracy.',adminbody,admin=True)
